String _rangeLabel(AppLocalizations l,AnalyticsTimeRange range)=>switch(range){AnalyticsTimeRange.today=>l.analyticsToday,AnalyticsTimeRange.last7Days=>l.analytics7Days,AnalyticsTimeRange.last30Days=>l.analytics30Days,AnalyticsTimeRange.last90Days=>l.analytics90Days,AnalyticsTimeRange.custom=>l.analyticsCustom};
class _RangePicker extends ConsumerWidget { const _RangePicker({this.custom=true});final bool custom;@override Widget build(BuildContext context,WidgetRef ref){final l=AppLocalizations.of(context)!,value=ref.watch(analyticsRangeProvider);return DropdownButton<AnalyticsTimeRange>(value:value==AnalyticsTimeRange.custom&&!custom?AnalyticsTimeRange.last30Days:value,items:[for(final r in AnalyticsTimeRange.values)if(custom||r!=AnalyticsTimeRange.custom)DropdownMenuItem(value:r,child:Text(_rangeLabel(l,r)))],onChanged:(v)=>ref.read(analyticsRangeProvider.notifier).state=v!);}}
Widget _async<T>(AsyncValue<T> value,Widget Function(T) data)=>value.when(data:data,loading:()=>const Center(child:CircularProgressIndicator()),error:(_,__)=>const _EmptyState(icon:Icons.cloud_off,title:'Data temporarily unavailable'));
class _EmptyState extends StatelessWidget { const _EmptyState({required this.icon,required this.title});final IconData icon;final String title;@override Widget build(BuildContext context)=>Center(child:Padding(padding:const EdgeInsets.all(32),child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(icon,size:52),const SizedBox(height:12),Text(title),TextButton(onPressed:(){},child:const Text('Retry'))])));}

