enum ProductSort { mostViewed,mostSearched,mostWatchlisted,highestDemand,lowestPerformance,stalePrice,outOfStock }
class ProductPerformanceScreen extends ConsumerStatefulWidget { const ProductPerformanceScreen({super.key});@override ConsumerState<ProductPerformanceScreen> createState()=>_ProductPerformanceScreenState();}
class _ProductPerformanceScreenState extends ConsumerState<ProductPerformanceScreen>{ProductSort sort=ProductSort.mostViewed;@override Widget build(BuildContext context){final l=AppLocalizations.of(context)!;return Scaffold(appBar:AppBar(title:Text(l.productPerformance)),body:_async(ref.watch(productPerformanceProvider),(raw){final items=[...raw];switch(sort){case ProductSort.mostViewed:items.sort((a,b)=>b.views.compareTo(a.views));break;case ProductSort.mostSearched:items.sort((a,b)=>b.searchAppearances.compareTo(a.searchAppearances));break;case ProductSort.mostWatchlisted:items.sort((a,b)=>b.watchlistAdds.compareTo(a.watchlistAdds));break;case ProductSort.highestDemand:items.sort((a,b)=>a.demand.index.compareTo(b.demand.index));break;case ProductSort.lowestPerformance:items.sort((a,b)=>a.performanceScore.compareTo(b.performanceScore));break;case ProductSort.stalePrice:items.sort((a,b)=>a.updatedAt.compareTo(b.updatedAt));break;case ProductSort.outOfStock:items.sort((a,b)=>a.inStock?1:-1);break;}return ListView(padding:const EdgeInsets.all(16),children:[DropdownButtonFormField(value:sort,decoration:InputDecoration(labelText:l.sortBy,border:const OutlineInputBorder()),items:[for(final v in ProductSort.values)DropdownMenuItem(value:v,child:Text(v.name))],onChanged:(v)=>setState(()=>sort=v!)),const SizedBox(height:12),if(items.isEmpty)_EmptyState(icon:Icons.inventory_2_outlined,title:l.noProductPerformance),for(final p in items)Card(child:ExpansionTile(title:Text(p.name),subtitle:Text('${NumberFormat.currency(locale:'en_IN',symbol:'₹',decimalDigits:0).format(p.price)} · ${p.inStock?l.inStock:l.outOfStock} · ${p.pricePosition}'),trailing:Chip(label:Text(p.demand.name)),children:[Padding(padding:const EdgeInsets.all(16),child:Wrap(spacing:18,runSpacing:10,children:[Text('Views ${p.views}'),Text('Search ${p.searchAppearances}'),Text('Comparisons ${p.comparisonViews}'),Text('Watchlists ${p.watchlistAdds}'),Text('Requests ${p.requests}'),Text('Offer clicks ${p.offerClicks}'),Text('Conversion ${p.conversionProxy.toStringAsFixed(1)}%'),Text('Updated ${DateFormat.yMMMd().format(p.updatedAt)}')]))]))]);}));}}

